package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.consense.domain.QwenGenerationAction;
import com.consense.repository.QwenGenerationActionRepository;
import com.consense.service.llm.QwenGenerationLedger;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.SimpleTransactionStatus;
import static com.consense.service.drafting.DraftReviewGraph.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Real ledger identity checks and real discovery conversion, with no external model or server. */
class DraftGroupedDispatchIdentityTest {
    static final String SHA=String.join("",Collections.nCopies(64,"a")),NOTE="Provide a project fact.";

    @Test void identicalWirePacketsFromDifferentActualGroupsCanEachDispatchOnce(){
        DraftAutomaticDiscovery.Plan plan=plan();List<Map<String,Object>> groups=DraftAutomaticDiscovery.planGroups(plan);assertEquals(2,groups.size());LedgerFixture ledger=new LedgerFixture();List<String> prompts=new ArrayList<>();Set<String> phases=new HashSet<>();
        for(Map<String,Object> group:groups){AtomicInteger dispatched=new AtomicInteger();String phase=DraftAutomationService.groupGenerationPhase(text(group.get("taskId")));assertTrue(phase.matches("[a-z][a-z0-9-]{0,47}"));assertTrue(phases.add(phase));Map<String,Object> receipt=DraftAutomaticDiscovery.processGroup((system,user)->{prompts.add(system+"\n"+user);return ledger.answer(phase,system,user,dispatched,false);},plan,group,true,dispatched::get);assertEquals(1,dispatched.get());assertEquals(1,receipt.get("modelCalls"));assertFalse(receipt.containsKey("failureStage"));assertTrue(list(receipt.get("stopReasons")).isEmpty());assertNotNull(receipt.get("rawResponse"));}
        assertEquals(prompts.get(0),prompts.get(1),"The real long source identities differ while the wire aliases are identical");assertNotEquals(groups.get(0).get("taskIds"),groups.get(1).get("taskIds"));assertEquals(2,ledger.action().getTotal());assertEquals(2,JsonUtils.parse(ledger.action().getReservationsJson()).size());
    }

    @Test void theSameGroupAndPayloadStillCannotReplayOrResetItsLedger(){
        DraftAutomaticDiscovery.Plan plan=plan();Map<String,Object> group=DraftAutomaticDiscovery.planGroups(plan).get(0);LedgerFixture ledger=new LedgerFixture();String phase=DraftAutomationService.groupGenerationPhase(text(group.get("taskId")));AtomicInteger firstDispatch=new AtomicInteger();Map<String,Object> first=DraftAutomaticDiscovery.processGroup((system,user)->ledger.answer(phase,system,user,firstDispatch,false),plan,group,true,firstDispatch::get);assertEquals(1,firstDispatch.get());String reservations=ledger.action().getReservationsJson();long deadline=ledger.action().getDeadlineEpochMs();AtomicInteger repeatedDispatch=new AtomicInteger();
        Map<String,Object> repeated=DraftAutomaticDiscovery.processGroup((system,user)->ledger.answer(phase,system,user,repeatedDispatch,false),plan,group,true,repeatedDispatch::get);assertEquals(0,repeatedDispatch.get());assertEquals(0,repeated.get("modelCalls"));assertEquals("blocked",repeated.get("status"));assertEquals("before_dispatch",repeated.get("failureStage"));assertEquals(Collections.singletonList("qwen_generation_already_reserved_no_replay"),repeated.get("stopReasons"));assertEquals(reservations,ledger.action().getReservationsJson());assertEquals(deadline,ledger.action().getDeadlineEpochMs());assertEquals(1,ledger.action().getTotal());assertNotNull(first.get("rawResponse"));assertNoInventedReplyIssues(repeated);
    }

    @Test void aSentCallWithoutAReplyKeepsItsUnknownReservationAndItsActualFailure(){
        DraftAutomaticDiscovery.Plan plan=plan();Map<String,Object> group=DraftAutomaticDiscovery.planGroups(plan).get(0);LedgerFixture ledger=new LedgerFixture();String phase=DraftAutomationService.groupGenerationPhase(text(group.get("taskId")));AtomicInteger sent=new AtomicInteger();Map<String,Object> receipt=DraftAutomaticDiscovery.processGroup((system,user)->ledger.answer(phase,system,user,sent,true),plan,group,true,sent::get);
        assertEquals(1,sent.get());assertEquals(1,receipt.get("modelCalls"));assertEquals("failed",receipt.get("status"));assertEquals("before_response",receipt.get("failureStage"));assertEquals(Collections.singletonList("synthetic_transport_failure"),receipt.get("stopReasons"));assertEquals("DISPATCH_UNKNOWN",JsonUtils.parse(ledger.action().getReservationsJson()).path(0).path("state").asText());assertNoInventedReplyIssues(receipt);AtomicInteger again=new AtomicInteger();Map<String,Object> repeated=DraftAutomaticDiscovery.processGroup((system,user)->ledger.answer(phase,system,user,again,false),plan,group,true,again::get);assertEquals(0,again.get());assertEquals(0,repeated.get("modelCalls"));assertEquals(1,ledger.action().getTotal());assertEquals("DISPATCH_UNKNOWN",JsonUtils.parse(ledger.action().getReservationsJson()).path(0).path("state").asText());
    }

    @Test void aReturnedInflightResultIsRetainedAfterAnotherGroupStopsBeforeDispatch()throws Exception{
        DraftAutomaticDiscovery.Plan plan=plan();List<Map<String,Object>> groups=DraftAutomaticDiscovery.planGroups(plan);CountDownLatch sent=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger dispatched=new AtomicInteger();ExecutorService worker=Executors.newSingleThreadExecutor();
        try{Future<Map<String,Object>> inflight=worker.submit(()->DraftAutomaticDiscovery.processGroup((system,user)->{dispatched.incrementAndGet();sent.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new IllegalStateException("synthetic_wait_timeout");}catch(InterruptedException stopped){Thread.currentThread().interrupt();throw new IllegalStateException(stopped);}return response(user);},plan,groups.get(0),true,dispatched::get));assertTrue(sent.await(1,TimeUnit.SECONDS));Map<String,Object> blocked=DraftAutomaticDiscovery.processGroup((system,user)->{throw new IllegalStateException("qwen_generation_already_reserved_no_replay");},plan,groups.get(1),true,()->0);assertEquals("blocked",blocked.get("status"));assertNoInventedReplyIssues(blocked);release.countDown();Map<String,Object> returned=inflight.get(5,TimeUnit.SECONDS);assertNotNull(returned.get("rawResponse"));assertEquals(1,returned.get("modelCalls"));List<Map<String,Object>> receipts=new ArrayList<>();for(Map<String,Object> parent:Arrays.asList(returned,blocked)){for(Object child:list(parent.get("taskReceipts")))receipts.add(map(child));receipts.add(parent);}Map<String,Object> graph=DraftAutomaticDiscovery.finish(obj("kind","consense-template-graph-v1","graph",obj("variables",new ArrayList<>(),"events",new ArrayList<>()),"sources",Collections.emptyList()),plan,receipts);assertEquals(1,nodes(graph).size());assertEquals("Current project fact",nodes(graph).get(0).get("nameEn"));assertEquals(1,list(state(graph).get("requirements")).size());assertEquals(1,map(state(graph).get("automaticDiscovery")).get("completedRequirementTasks"));assertEquals(1,map(state(graph).get("automaticDiscovery")).get("failedRequirementTasks"));
        }finally{release.countDown();worker.shutdownNow();}
    }

    @Test void anActualReplyMissingOutcomesStillFailsTheExistingSchemaChecks(){
        DraftAutomaticDiscovery.Plan plan=plan();AtomicInteger sent=new AtomicInteger();Map<String,Object> receipt=DraftAutomaticDiscovery.processGroup((system,user)->{sent.incrementAndGet();return "{\"nodes\":[],\"requirements\":[]}";},plan,DraftAutomaticDiscovery.planGroups(plan).get(0),true,sent::get);assertEquals(1,receipt.get("modelCalls"));assertNotNull(receipt.get("rawResponse"));assertFalse(receipt.containsKey("failureStage"));assertTrue(list(receipt.get("stopReasons")).contains("task_outcomes_array_required"));assertTrue(JsonUtils.write(receipt).contains("group_task_outcome_missing_or_invalid"));
    }

    static void assertNoInventedReplyIssues(Map<String,Object> receipt){assertFalse(receipt.containsKey("rawResponse"));assertFalse(receipt.containsKey("retainedResponse"));assertFalse(JsonUtils.write(receipt).contains("group_task_outcome_missing_or_invalid"));assertFalse(JsonUtils.write(receipt).contains("task_outcomes_array_required"));assertFalse(JsonUtils.write(receipt).contains("group_nodes_array_required"));assertFalse(JsonUtils.write(receipt).contains("requirements_array_required"));for(Object child:list(receipt.get("taskReceipts"))){assertTrue(list(map(child).get("nodes")).isEmpty());assertTrue(list(map(child).get("requirements")).isEmpty());assertEquals(receipt.get("status"),map(child).get("status"));}}
    static String response(String user){JsonNode packet=JsonUtils.parse(user),group=packet.has("group")?packet.path("group"):packet;String task=group.path("instructions").path(0).path("sourceTaskId").asText();return JsonUtils.write(obj("nodes",Collections.singletonList(obj("id","fact","sourceTaskId",task,"type","text","role","content","nameEn","Current project fact","sourceQuote",NOTE,"options",Collections.emptyList(),"branches",Collections.emptyList(),"effects",Collections.emptyList())),"requirements",Collections.singletonList(obj("id","requirement","sourceTaskId",task,"sourceQuote",NOTE,"kind","input","nodeIds",Collections.singletonList("fact"))),"taskOutcomes",Collections.singletonList(obj("sourceTaskId",task,"status","identified"))));}
    static DraftAutomaticDiscovery.Plan plan(){ObjectNode source=JsonUtils.mapper().createObjectNode().put("id","1").put("sourceDocumentId",1).put("fileKey","SCT").put("format","docx").put("sourceSha256",SHA).put("evidenceStatus","bound");for(String field:Arrays.asList("sourceMembers","paragraphs","guidanceNotes","groups","conditions","markerCandidates"))source.putArray(field);for(String suffix:Arrays.asList("a","b")){String memberId="member-"+suffix;ObjectNode member=source.withArray("sourceMembers").addObject().put("id",memberId).put("identityStatus","source_bound");member.putObject("sourcePosition").put("sourceSha256",SHA).put("partName","word/document.xml").put("nodePath","/"+suffix);member.putObject("textObservation").put("text",NOTE);ObjectNode note=source.withArray("guidanceNotes").addObject().put("id","note-"+suffix).put("text",NOTE).put("captureComplete",true);note.putArray("orderedMemberIds").add(memberId);note.putArray("memberRanges").addObject().put("memberId",memberId).put("channel","text").put("start",0).put("end",NOTE.length());}return DraftAutomaticDiscovery.plan(Collections.singletonList(source));}

    static final class LedgerFixture {
        final Map<String,QwenGenerationAction> rows=new HashMap<>();final QwenGenerationLedger ledger;
        LedgerFixture(){QwenGenerationActionRepository actions=mock(QwenGenerationActionRepository.class);PlatformTransactionManager transactions=mock(PlatformTransactionManager.class);when(transactions.getTransaction(any())).thenAnswer(call->new SimpleTransactionStatus());when(actions.lockAction(anyString())).thenAnswer(call->Optional.ofNullable(rows.get(call.getArgument(0))));when(actions.saveAndFlush(any())).thenAnswer(call->{QwenGenerationAction action=call.getArgument(0);rows.put(action.getId(),action);return action;});when(actions.save(any())).thenAnswer(call->{QwenGenerationAction action=call.getArgument(0);rows.put(action.getId(),action);return action;});ledger=new QwenGenerationLedger(actions,transactions);ledger.open("draft:identity",SHA,new QwenGenerationLedger.Limits(10,10,10,60000));}
        QwenGenerationAction action(){return rows.get("draft:identity");}
        String answer(String phase,String system,String user,AtomicInteger dispatched,boolean fail){QwenGenerationLedger.Reservation reservation=ledger.reserve("draft:identity",SHA,phase,DraftAdoption.hash(system+"\n"+user),true);ledger.dispatch(reservation);dispatched.incrementAndGet();if(fail){ledger.unknown(reservation,"SyntheticTransportFailure");throw new IllegalStateException("synthetic_transport_failure");}String result=response(user);ledger.complete(reservation,Collections.singletonMap("responseSha256",DraftAdoption.hash(result)));return result;}
    }
}
